// ***************
// Filename: i2c_top.sv
// Author: FPGA Cores 4 U
// Description: i2c_master with its AXI4-Lite register interface, the block
//   designs and testbenches instantiate: the register map i2c_master_regs
//   (u_regs, src/include/i2c_master_regs.sv, ID "I2CM", VERSION and DATE at
//   0x00-0x08, the registers from 0x10) and the logic i2c_master (u_core,
//   src/i2c_master.sv), joined by the register interface i2c_master_regs_if
//   (u_regs_if). Generated by ip/scripts/regmap_gen.py from
//   i2c_master_regs.json and the ports of i2c_master: regenerate after
//   changing either. Clock - aclk. Reset - synchronous active low aresetn.
// Date: 2026-10-20
module i2c_top #(
  parameter int CLK_HZ = 100_000_000,
  parameter int SCL_HZ = 100_000,
  parameter int FIFO_DEPTH = 512
) (
  input  logic aclk,
  input  logic aresetn,
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // s_axis: axis_if.slave (ip/shared/src/interfaces/axis_if.sv), DATA_W = 8
  axis_if.slave s_axis,
  // m_axis: axis_if.master (ip/shared/src/interfaces/axis_if.sv), DATA_W = 8
  axis_if.master m_axis,
  // i2c: i2c_if.master (ip/shared/src/interfaces/i2c_if.sv) {scl_i=scl_i scl_o=scl_o scl_t=scl_t sda_i=sda_i sda_o=sda_o sda_t=sda_t}
  i2c_if.master i2c,
  output logic irq_o
);
  // register interface between the register map and the logic
  i2c_master_regs_if u_regs_if ();

  i2c_master_regs #(
    .DIV_RST(((CLK_HZ / (4 * SCL_HZ)) > ((CLK_HZ / 1000 * (SCL_HZ <= 100_000 ? 4700 : SCL_HZ <= 400_000 ? 1300 : 500) + 1_999_999) / 2_000_000) ? (CLK_HZ / (4 * SCL_HZ)) : ((CLK_HZ / 1000 * (SCL_HZ <= 100_000 ? 4700 : SCL_HZ <= 400_000 ? 1300 : 500) + 1_999_999) / 2_000_000)) - 1)
  ) u_regs (
    .aclk,
    .aresetn,
    .s_axil(s_axil),
    .r(u_regs_if)
  );
  i2c_master #(
    .CLK_HZ(CLK_HZ),
    .SCL_HZ(SCL_HZ),
    .FIFO_DEPTH(FIFO_DEPTH)
  ) u_core (
    .aclk,
    .aresetn,
    .s_axis,
    .m_axis,
    .i2c,
    .regs(u_regs_if),
    .irq_o
  );
endmodule
